<div class="row g-4">
<section class="col-lg-6"><div class="card"><div class="card-body"><h2 class="h5">Create account</h2><form method="post" action="/admin/users" class="row g-2"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><div class="col-3"><input type="number" min="1" name="id" class="form-control" placeholder="Edit ID"></div><div class="col-9"><input required class="form-control" name="name" maxlength="150" placeholder="Full name"></div><div class="col-12"><input required type="email" class="form-control" name="email" placeholder="Email"></div><div class="col-6"><select name="role" class="form-select"><option value="teacher">Teacher</option><option value="student">Student</option><option value="admin">Administrator</option></select></div><div class="col-6"><input type="password" minlength="8" name="password" class="form-control" placeholder="Password (required for new account)"></div><div class="col-12"><label><input type="checkbox" name="is_active" checked> Active</label></div><div><button class="btn btn-primary">Save account</button></div></form><p class="small text-muted mt-2 mb-0">To edit an existing record, use its ID in the corresponding form below.</p></div></div></section>
<section class="col-lg-6"><div class="card"><div class="card-body"><h2 class="h5">Create / update course</h2><form method="post" action="/admin/courses" class="row g-2"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><div class="col-3"><input type="number" min="1" name="id" class="form-control" placeholder="Edit ID"></div><div class="col-9"><input required name="code" class="form-control" placeholder="Course code"></div><div class="col-12"><input required name="title" class="form-control" placeholder="Course title"></div><div class="col-12"><textarea class="form-control" name="description" placeholder="Description"></textarea></div><div class="col-12"><label><input type="checkbox" name="is_active" checked> Active</label></div><div><button class="btn btn-primary">Save course</button></div></form></div></div></section>
<section class="col-12"><div class="card"><div class="card-body"><h2 class="h5">Create / update section</h2><form method="post" action="/admin/sections" class="row g-2"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><div class="col-md-2"><input type="number" min="1" name="id" class="form-control" placeholder="Edit ID"></div><div class="col-md-3"><select class="form-select" required name="course_id"><option value="">Choose course</option><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['code'].' · '.$c['title']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select class="form-select" required name="teacher_id"><option value="">Choose teacher</option><?php foreach($users as $u): if($u['role']==='teacher' && $u['is_active']): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endif; endforeach ?></select></div><div class="col-md-2"><input required name="name" maxlength="120" class="form-control" placeholder="Section name"></div><div class="col-md-2"><input name="enrollment_code" maxlength="32" class="form-control" placeholder="Code (auto if new)"></div><div class="col-12"><label><input type="checkbox" name="is_active" checked> Active</label></div><div><button class="btn btn-primary">Save section</button></div></form></div></div></section>
</div>
<h2 class="h5 mt-4">Accounts</h2><div class="table-responsive"><table class="table table-striped table-sm"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Active</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= (int)$u['id'] ?></td><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['role']) ?></td><td><?= $u['is_active']?'Yes':'No' ?></td></tr><?php endforeach ?></tbody></table></div>
<h2 class="h5 mt-4">Courses</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>ID</th><th>Code</th><th>Title</th><th>Active</th></tr></thead><tbody><?php foreach($courses as $c): ?><tr><td><?= (int)$c['id'] ?></td><td><?= e($c['code']) ?></td><td><?= e($c['title']) ?></td><td><?= $c['is_active']?'Yes':'No' ?></td></tr><?php endforeach ?></tbody></table></div>
<h2 class="h5 mt-4">Sections and enrollment codes</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>ID</th><th>Course</th><th>Section</th><th>Teacher</th><th>Enrollment code</th><th>Active</th></tr></thead><tbody><?php foreach($sections as $s): ?><tr><td><?= (int)$s['id'] ?></td><td><?= e($s['course_code']) ?></td><td><?= e($s['name']) ?></td><td><?= e($s['teacher_name']) ?></td><td><code><?= e($s['enrollment_code']) ?></code></td><td><?= $s['is_active']?'Yes':'No' ?></td></tr><?php endforeach ?></tbody></table></div>
